scwin.dbClick = function(id) {
	var el = scwin.__getDom($p.id + id);
	var evt = document.createEvent('MouseEvents');
	evt.initEvent('dblclick', true, false);
	el.dispatchEvent(evt);
};
scwin.addEl = function(id, array) {
	var dataColId = WebSquare.util.getDataPrefix("col_id");
	var arr = jQuery("*[" + dataColId + "='" + id + "']");
	for (var i = 0; i < arr.length; i++) {
		array.push(arr[i].innerText);
	}
	return array;
};
scwin.checktype = function() {
	return typeof document.getElementsByClassName('w2grid_head_sort_asc')[0];
};
scwin.setVal1 = function() {
	scwin.addEl('col3', initArr);
};
scwin.setVal2 = function() {
	scwin.addEl('col3', beforeArr);
};
scwin.checkVal = function() {
	return initArr.length == beforeArr.length && initArr.every(function(v, i) {
		return v === beforeArr[i]
	});
};
